#!/usr/bin/env bash
# Check that a commit message subject follows Conventional Commits.
# Usage: check-commit-msg.sh <file>   (as used by the commit-msg git hook)
#        echo "<subject>" | check-commit-msg.sh
set -euo pipefail

# Subject = first non-empty line that isn't a git comment
subject=$(grep -v '^#' "${1:-/dev/stdin}" | grep -m1 -v '^[[:space:]]*$' || true)

types='feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert'
pattern="^(${types})(\([a-z0-9._/-]+\))?!?: [^ ].*"
# Messages generated by git itself
generated='^(Merge |Revert "|fixup! |squash! |amend! )'

if [[ "$subject" =~ $pattern || "$subject" =~ $generated ]]; then
    exit 0
fi

cat >&2 <<MSG
error: commit message does not follow Conventional Commits:

    ${subject:-<empty>}

Expected:  <type>(<optional scope>)<optional !>: <description>
Types:     ${types//|/, }
Examples:  feat: add gradient descent optimizer
           fix(rust): handle empty input arrays
           chore(deps): bump pyo3 to 0.31
MSG
exit 1
